$_MODULE['<{sudemi}prestashop>sudemi_1bd983391f0e9675405614baf1ed990c'] = 'sudemi דחתה בקשות מהאתר הזה: החנות הזו מחוברת ל-sudemi בכתובת אחרת (%s). אם האתר הזה הוא עותק בדיקות (staging) או גיבוי משוחזר, יש לנתק את sudemi כאן. אם החנות עברה לכתובת הזו, יש לחבר אותה מחדש.';
$_MODULE['<{sudemi}prestashop>sudemi_ce1ed32e41d97b80d80b33148f53f789'] = 'sudemi דחתה בקשות מהאתר הזה: החנות הזו מחוברת ל-sudemi בכתובת אחרת. אם האתר הזה הוא עותק בדיקות (staging) או גיבוי משוחזר, יש לנתק את sudemi כאן. אם החנות עברה לכתובת הזו, יש לחבר אותה מחדש.';
$_MODULE['<{sudemi}prestashop>sudemi_432e26275e5095d41313deeb350c7ea2'] = 'קודם חברו את החנות הזו ל-sudemi.';
$_MODULE['<{sudemi}prestashop>sudemi_a473565a143cf3cdb01895753a94ccab'] = 'ההחזרה אושרה. הקונה יתבקש לשלוח את הפריט בחזרה. כשהפריט חוזר, החזירו את הכסף על ההזמנה הזו כרגיל (סטטוס הוחזר, או זיכוי עבור חלק ממנה): ההחזר מגיע לקונה דרך sudemi וסוגר את הבקשה.';
$_MODULE['<{sudemi}prestashop>sudemi_cb2539cea371b3e5736c3444acbfccf9'] = 'ההחזרה נדחתה. sudemi מציגה לקונה את הסיבה שלכם.';
$_MODULE['<{sudemi}prestashop>sudemi_8af7448f2470dbdf3e3c52b23b771e9d'] = 'בקשת ההחזרה הזו כבר נענתה (ב-sudemi, או על ידי sudemi לאחר המועד). לא שונה דבר.';
$_MODULE['<{sudemi}prestashop>sudemi_9fba5e140e3eeeef1fb479338a5f0a00'] = 'ל-sudemi אין בקשת החזרה פתוחה להזמנה הזו. היא הוסרה מהרשימה.';
$_MODULE['<{sudemi}prestashop>sudemi_77045abe2681e10ec8585af1568a531d'] = 'כדי לדחות החזרה, ציינו סיבה. הקונה יראה אותה.';
$_MODULE['<{sudemi}prestashop>sudemi_f56cb5d64a1b05252377f64a8a6995b3'] = 'sudemi לא קיבלה את התשובה הזו. דחייה דורשת סיבה; בדקו אותה ונסו שוב.';
$_MODULE['<{sudemi}prestashop>sudemi_98cb3df4ed609dceaddc55efce570395'] = 'בקשות החזרה';
$_MODULE['<{sudemi}prestashop>sudemi_0eba7b42b6c53cdc949279b9d1e6ac3c'] = 'קונים מבקשים להחזיר את ההזמנות שנמסרו האלה. ענו על כל אחת לפני מועד התשובה שלה: אשרו, או דחו עם סיבה (הקונה יראה אותה). ללא תשובה, sudemi מחליטה. לאחר האישור, החזירו את הכסף על ההזמנה כשהפריט חוזר.';
